1	export interface Item {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	}
7	
8	export interface QuoteStep {
9	  op: "quote";
10	  items: Item[];
11	}
12	
13	export interface Damage {
14	  itemType: string;
15	  amount: number;
16	}
17	
18	export interface Incident {
19	  cause: string;
20	  damages: Damage[];
21	}
22	
23	export interface ClaimStep {
24	  op: "claim";
25	  policy: number;
26	  incident: Incident;
27	}
28	
29	export type Step = QuoteStep | ClaimStep;
30	
31	export interface Customer {
32	  yearsWithMHPCO: number;
33	}
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface ScenarioOutput {
41	  results: unknown[];
42	}
43	
44	const PROCESSING_FEE = 5;
45	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
46	const LOYALTY_YEARS = 2;
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
49	
50	/** The MHPCO insures exactly these item types; anything else is unknown. */
51	interface ItemTypeTerms {
52	  basePremium: number;
53	  insuranceValue: number;
54	}
55	
56	const ITEM_TYPES: Record<string, ItemTypeTerms | undefined> = {
57	  sword: { basePremium: 100, insuranceValue: 1000 },
58	  amulet: { basePremium: 60, insuranceValue: 600 },
59	  staff: { basePremium: 80, insuranceValue: 800 },
60	  potion: { basePremium: 40, insuranceValue: 400 },
61	  rune: { basePremium: 25, insuranceValue: 250 },
62	  moonstone: { basePremium: 25, insuranceValue: 250 },
63	};
64	
65	const termsOfType = (type: string): ItemTypeTerms => {
66	  const terms = ITEM_TYPES[type];
67	  if (terms === undefined) {
68	    throw new Error(`unknown item type: ${type}`);
69	  }
70	  return terms;
71	};
72	
73	const basePremiumOfType = (type: string): number => termsOfType(type).basePremium;
74	
75	const insuranceValueOfType = (type: string): number => termsOfType(type).insuranceValue;
76	
77	const CURSE_SURCHARGE_RATE = 0.5;
78	const HIGH_ENCHANTMENT_LEVEL = 5;
79	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
80	
81	const isCursed = (item: Item): boolean => item.cursed === true;
82	const isHighlyEnchanted = (item: Item): boolean =>
83	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
84	
85	/** Item-specific modifiers apply to the base premium of the affected item only. */
86	const itemSurchargesOf = (item: Item): number => {
87	  const basePremium = basePremiumOfType(item.type);
88	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
89	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
90	    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
91	    : 0;
92	  return curseSurcharge + highEnchantmentSurcharge;
93	};
94	
95	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
96	const COMPONENT_BLOCK_SIZE = 3;
97	const COMPONENT_BLOCK_PREMIUM = 60;
98	
99	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
100	
101	const countByType = (items: Item[]): Map<string, number> => {
102	  const counts = new Map<string, number>();
103	  for (const item of items) {
104	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
105	  }
106	  return counts;
107	};
108	
109	/**
110	 * Items of one type are normally priced individually. The exception is
111	 * components: exactly 3 alike ones form a "building block" priced as a unit.
112	 */
113	const typeGroupPremium = (type: string, count: number): number =>
114	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
115	    ? COMPONENT_BLOCK_PREMIUM
116	    : count * basePremiumOfType(type);
117	
118	const policyBasePremiumOf = (items: Item[]): number =>
119	  [...countByType(items)].reduce(
120	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
121	    0,
122	  );
123	
124	const isLongStanding = (customer: Customer): boolean =>
125	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
126	
127	/** What the policy-wide modifiers are judged against, beyond the items themselves. */
128	interface QuoteContext {
129	  customer: Customer;
130	  isFollowUpContract: boolean;
131	}
132	
133	/**
134	 * Policy-wide modifiers are signed rates charged against the policy base
135	 * premium: surcharges positive, discounts negative.
136	 */
137	const policyModifierRateFor = (context: QuoteContext): number =>
138	  INITIAL_ASSESSMENT_SURCHARGE_RATE -
139	  (isLongStanding(context.customer) ? LOYALTY_DISCOUNT_RATE : 0) -
140	  (context.isFollowUpContract ? FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0);
141	
142	const itemSurchargesOfPolicy = (items: Item[]): number =>
143	  items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
144	
145	/** Kept as an exact fraction — only the final premium is rounded. */
146	const premiumBeforeRounding = (items: Item[], context: QuoteContext): number => {
147	  const policyBasePremium = policyBasePremiumOf(items);
148	  const policyModifiers = policyBasePremium * policyModifierRateFor(context);
149	  return policyBasePremium + itemSurchargesOfPolicy(items) + policyModifiers + PROCESSING_FEE;
150	};
151	
152	/** Rounded up, in the MHPCO's favour. */
153	const finalPremiumFor = (items: Item[], context: QuoteContext): number =>
154	  Math.ceil(premiumBeforeRounding(items, context));
155	
156	const DEDUCTIBLE = 100;
157	const CAP_MULTIPLIER = 2;
158	
159	const insuranceSumOf = (items: Item[]): number =>
160	  items.reduce((sum, item) => sum + insuranceValueOfType(item.type), 0);
161	
162	/** A policy created by a quote step, tracked so later claims can draw on it. */
163	interface Policy {
164	  items: Item[];
165	  remainingCap: number;
166	}
167	
168	/** The most a policy will ever pay out, across all claims against it. */
169	const capFor = (items: Item[]): number => insuranceSumOf(items) * CAP_MULTIPLIER;
170	
171	const openPolicyFor = (items: Item[]): Policy => ({ items, remainingCap: capFor(items) });
172	
173	const CLAIM_HIGH_ENCHANTMENT_LEVEL = 8;
174	const CLAIM_HIGH_ENCHANTMENT_RATE = 0.5;
175	
176	/**
177	 * Unrelated to the high-enchantment premium surcharge: that one is judged
178	 * against HIGH_ENCHANTMENT_LEVEL, this one against its own, higher threshold.
179	 */
180	const qualifiesForHalfReimbursement = (insuredItem: Item): boolean =>
181	  (insuredItem.enchantment ?? 0) >= CLAIM_HIGH_ENCHANTMENT_LEVEL;
182	
183	/** The share of the damage the MHPCO reimburses, before the deductible. */
184	const reimbursementRateFor = (insuredItem: Item): number =>
185	  qualifiesForHalfReimbursement(insuredItem) ? CLAIM_HIGH_ENCHANTMENT_RATE : 1;
186	
187	const payoutForDamage = (damage: Damage, insuredItem: Item): number => {
188	  if (damage.amount < 0) {
189	    throw new Error(`damage amount must not be negative: ${String(damage.amount)}`);
190	  }
191	  return damage.amount * reimbursementRateFor(insuredItem) - DEDUCTIBLE;
192	};
193	
194	const insuredItemFor = (damage: Damage, policy: Policy): Item => {
195	  const insuredItem = policy.items.find((item) => item.type === damage.itemType);
196	  if (insuredItem === undefined) {
197	    throw new Error(`claim references uninsured item type ${damage.itemType}`);
198	  }
199	  return insuredItem;
200	};
201	
202	interface Settlement {
203	  payout: number;
204	  remainingCap: number;
205	}
206	
207	/**
208	 * Draws against the policy's remaining cap, which it depletes.
209	 * Rounded down, in the MHPCO's favour.
210	 */
211	const settleClaim = (step: ClaimStep, policy: Policy): Settlement => {
212	  const claimed = step.incident.damages.reduce(
213	    (sum, damage) => sum + payoutForDamage(damage, insuredItemFor(damage, policy)),
214	    0,
215	  );
216	  const payout = Math.floor(Math.min(claimed, policy.remainingCap));
217	
218	  policy.remainingCap -= payout;
219	  return { payout, remainingCap: policy.remainingCap };
220	};
221	
222	const policyReferencedBy = (step: ClaimStep, policies: Map<number, Policy>): Policy => {
223	  const policy = policies.get(step.policy);
224	  if (policy === undefined) {
225	    throw new Error(`claim references unknown policy at step ${String(step.policy)}`);
226	  }
227	  return policy;
228	};
229	
230	export const runScenario = (scenario: Scenario): ScenarioOutput => {
231	  const policies = new Map<number, Policy>();
232	
233	  const results = scenario.steps.map((step, stepIndex) => {
234	    if (step.op === "claim") {
235	      return settleClaim(step, policyReferencedBy(step, policies));
236	    }
237	
238	    // Every quote but the first is a follow-up contract for this customer.
239	    const isFollowUpContract = policies.size > 0;
240	    policies.set(stepIndex, openPolicyFor(step.items));
241	
242	    return {
243	      premium: finalPremiumFor(step.items, { customer: scenario.customer, isFollowUpContract }),
244	    };
245	  });
246	
247	  return { results };
248	};
